class Solution {
public:
    long long minimumTotalCost(vector<int>& a, vector<int>& b){
        int n=a.size(); long long base=0; int mx=0,v=0,m=0;
        unordered_map<int,int> cnt;
        vector<bool> inS(n,false);
        for(int i=0;i<n;i++) if(a[i]==b[i]){base+=i;inS[i]=true;m++;if(++cnt[a[i]]>mx){mx=cnt[a[i]];v=a[i];}}
        if(m==0) return 0;
        if(2*mx<=m) return base;
        for(int j=0;j<n;j++) if(!inS[j]&&b[j]!=v) return base+j;
        return -1;
    }
};

