class Solution {
    public long minimumTotalCost(int[] a, int[] b){
        int n=a.length,m=0,mx=0,v=0; long base=0;
        Map<Integer,Integer> cnt=new HashMap<>();
        boolean[] inS=new boolean[n];
        for(int i=0;i<n;i++) if(a[i]==b[i]){base+=i;inS[i]=true;m++;int c=cnt.merge(a[i],1,Integer::sum);if(c>mx){mx=c;v=a[i];}}
        if(m==0) return 0;
        if(2*mx<=m) return base;
        for(int j=0;j<n;j++) if(!inS[j]&&b[j]!=v) return base+j;
        return -1;
    }
}

