var minimumTotalCost = function(a, b) {
    const n=a.length; let base=0,m=0,mx=0,v=0;
    const cnt=new Map(), inS=Array(n).fill(false);
    for(let i=0;i<n;i++) if(a[i]===b[i]){base+=i;inS[i]=true;m++;const c=(cnt.get(a[i])||0)+1;cnt.set(a[i],c);if(c>mx){mx=c;v=a[i];}}
    if(m===0) return 0;
    if(2*mx<=m) return base;
    for(let j=0;j<n;j++) if(!inS[j]&&b[j]!==v) return base+j;
    return -1;
};
